  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur la légalité de la décision de l'AXA de mettre fin aux prestations au 8 mai 2023.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "L'accident du 8 février 2023 s'est produit alors que la personne assurée glissait en marchant et a chuté sur le côté droit, tentant de se retenir avec le bras.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Selon l'appréciation du médecin-conseil de l'AXA, les lésions de la coiffe des rotateurs et du cartilage de l'épaule droite sont dues à des altérations dégénératives importantes.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La répartition du fardeau de la preuve concernant la disparition du lien de causalité ne s'applique qu'aux lésions qui étaient réellement en discussion lors de la reconnaissance de la responsabilité de l'assureur.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "En l'espèce, la preuve que ces lésions ultérieurement constatées sont des suites de l'accident incombe à la personne assurée, et non à l'AXA.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que l'AXA a retenu à juste titre l'atteinte du statu quo sine vel ante après une aggravation passagère d'un état dégénératif préexistant, justifiant la fin des prestations au 8 mai 2023.",
      "b_propositions": ["P6"]
    }
  ]
}
